package main

import (
	"database/sql"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int
	Name  string
	Price float64
	Desc  string
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("cat")
	sortBy := r.URL.Query().Get("sort")

	// Validate sort parameter (allowlist)
	validSorts := map[string]bool{"name": true, "price": true, "id": true}
	if !validSorts[sortBy] {
		sortBy = "id"
	}

	// Build query - category is user-controlled
	var query string
	if category != "" {
		// Developer note: category comes from a dropdown in the UI
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = '%s' ORDER BY %s",
			category, sortBy,
		)
	} else {
		query = fmt.Sprintf("SELECT id, name, price, description FROM products ORDER BY %s", sortBy)
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		rows.Scan(&p.ID, &p.Name, &p.Price, &p.Desc)
		products = append(products, p)
	}

	tmpl := template.Must(template.New("results").Parse(`
		<html><body><h1>Products</h1>
		{{range .}}<div>{{.Name}} - ${{.Price}}</div>{{end}}
		</body></html>
	`))
	tmpl.Execute(w, products)
}

// healthCheck for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

// adminExport uses parameterized queries properly
func adminExport(w http.ResponseWriter, r *http.Request) {
	authHeader := r.Header.Get("X-Internal-Auth")
	if authHeader != os.Getenv("INTERNAL_SECRET") {
		http.Error(w, "forbidden", 403)
		return
	}
	catFilter := r.URL.Query().Get("cat")
	rows, err := db.Query("SELECT id, name, price FROM products WHERE category = $1", catFilter)
	if err != nil {
		http.Error(w, "error", 500)
		return
	}
	defer rows.Close()
	for rows.Next() {
		var id int
		var name string
		var price float64
		rows.Scan(&id, &name, &price)
		fmt.Fprintf(w, "%d,%s,%.2f\n", id, name, price)
	}
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Sanitize log output to prevent log injection
		path := strings.ReplaceAll(r.URL.Path, "\n", "")
		log.Printf("[%s] %s %s", r.RemoteAddr, r.Method, path)
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/search", searchProducts)
	mux.HandleFunc("/health", healthCheck)
	mux.HandleFunc("/admin/export", adminExport)

	server := &http.Server{
		Addr:    ":8080",
		Handler: loggingMiddleware(mux),
	}
	log.Fatal(server.ListenAndServe())
}
